/**
 * Byte-level helpers shared by the hashing / KDF modules.
 *
 * Everything here works on `Uint8Array`, which stands in for Python's
 * immutable `bytes` objects.
 */

const utf8Encoder = new TextEncoder();

const HEX_DIGITS = '0123456789abcdef';

/**
 * Normalise a passphrase / salt argument into raw bytes.
 *
 * Mirrors pbkdf2.py's `_setup()`: text is encoded as UTF-8, raw byte
 * sequences pass through untouched, anything else is a TypeError.
 */
export function toBytes(value, label = 'value') {
  if (typeof value === 'string') {
    return utf8Encoder.encode(value);
  }
  if (value instanceof Uint8Array) {
    return value;
  }
  throw new TypeError(`${label} must be a string or a Uint8Array`);
}

/** Lowercase hex rendering, identical to Python's `bytes.hex()`. */
export function toHex(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i += 1) {
    const byte = bytes[i];
    out += HEX_DIGITS[byte >>> 4] + HEX_DIGITS[byte & 0x0f];
  }
  return out;
}

/** Concatenate a list of byte arrays, like `b"".join(blocks)`. */
export function concatBytes(chunks) {
  let total = 0;
  for (const chunk of chunks) {
    total += chunk.length;
  }
  const out = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.length;
  }
  return out;
}

/** Write a 32-bit unsigned integer in big-endian order, like `pack("!L", n)`. */
export function writeUint32BE(target, offset, value) {
  target[offset] = (value >>> 24) & 0xff;
  target[offset + 1] = (value >>> 16) & 0xff;
  target[offset + 2] = (value >>> 8) & 0xff;
  target[offset + 3] = value & 0xff;
  return target;
}

/** In-place `target ^= source`, the accumulator half of pbkdf2.py's strxor. */
export function xorInto(target, source) {
  for (let i = 0; i < target.length; i += 1) {
    target[i] ^= source[i];
  }
  return target;
}

