/**
 * SHA-1 (FIPS 180-4) implemented from scratch in plain JavaScript.
 *
 * The digest object is deliberately shaped like a `hashlib` object
 * (`update()` / `digest()`) and additionally supports `copy()`, which lets
 * HMAC snapshot the state right after the key pad block has been absorbed.
 */

import { writeUint32BE } from './bytes.mjs';

export const BLOCK_SIZE = 64;
export const DIGEST_SIZE = 20;

const INITIAL_STATE = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];

// Round constants for the four 20-round groups.
const K0 = 0x5a827999;
const K1 = 0x6ed9eba1;
const K2 = 0x8f1bbcdc;
const K3 = 0xca62c1d6;

// Message schedule scratch space, reused across calls (single-threaded, and
// `compress` never recurses).
const W = new Uint32Array(80);

function rotl(value, shift) {
  return ((value << shift) | (value >>> (32 - shift))) >>> 0;
}

/** Absorb one 64-byte block at `offset` into the five-word state `h`. */
function compress(h, block, offset) {
  for (let i = 0; i < 16; i += 1) {
    const p = offset + i * 4;
    W[i] = ((block[p] << 24) | (block[p + 1] << 16) | (block[p + 2] << 8) | block[p + 3]) >>> 0;
  }
  for (let i = 16; i < 80; i += 1) {
    W[i] = rotl(W[i - 3] ^ W[i - 8] ^ W[i - 14] ^ W[i - 16], 1);
  }

  let a = h[0];
  let b = h[1];
  let c = h[2];
  let d = h[3];
  let e = h[4];

  for (let i = 0; i < 80; i += 1) {
    let f;
    let k;
    if (i < 20) {
      f = (b & c) | (~b & d);
      k = K0;
    } else if (i < 40) {
      f = b ^ c ^ d;
      k = K1;
    } else if (i < 60) {
      f = (b & c) | (b & d) | (c & d);
      k = K2;
    } else {
      f = b ^ c ^ d;
      k = K3;
    }
    // The five addends are each < 2^32, so the sum stays exact in a double
    // and `>>> 0` performs the mod-2^32 wrap.
    const t = (rotl(a, 5) + (f >>> 0) + e + k + W[i]) >>> 0;
    e = d;
    d = c;
    c = rotl(b, 30);
    b = a;
    a = t;
  }

  h[0] = (h[0] + a) >>> 0;
  h[1] = (h[1] + b) >>> 0;
  h[2] = (h[2] + c) >>> 0;
  h[3] = (h[3] + d) >>> 0;
  h[4] = (h[4] + e) >>> 0;
}

export class Sha1 {
  constructor() {
    this._state = Uint32Array.from(INITIAL_STATE);
    this._block = new Uint8Array(BLOCK_SIZE);
    this._pending = 0;
    this._totalBytes = 0;
  }

  /** Independent snapshot of the current absorption state. */
  copy() {
    const clone = Object.create(Sha1.prototype);
    clone._state = this._state.slice();
    clone._block = this._block.slice();
    clone._pending = this._pending;
    clone._totalBytes = this._totalBytes;
    return clone;
  }

  update(data) {
    this._totalBytes += data.length;
    let offset = 0;

    if (this._pending > 0) {
      const take = Math.min(BLOCK_SIZE - this._pending, data.length);
      this._block.set(data.subarray(0, take), this._pending);
      this._pending += take;
      offset = take;
      if (this._pending === BLOCK_SIZE) {
        compress(this._state, this._block, 0);
        this._pending = 0;
      }
    }

    while (data.length - offset >= BLOCK_SIZE) {
      compress(this._state, data, offset);
      offset += BLOCK_SIZE;
    }

    if (offset < data.length) {
      const rest = data.subarray(offset);
      this._block.set(rest, 0);
      this._pending = rest.length;
    }

    return this;
  }

  /** Finalise without disturbing this object, like `hashlib`'s digest(). */
  digest() {
    const state = this._state.slice();

    // 0x80 terminator plus a 64-bit length must fit; 55 free bytes is the cut-off.
    const tail = new Uint8Array(this._pending <= 55 ? BLOCK_SIZE : BLOCK_SIZE * 2);
    tail.set(this._block.subarray(0, this._pending));
    tail[this._pending] = 0x80;

    const bitLength = this._totalBytes * 8;
    writeUint32BE(tail, tail.length - 8, Math.floor(bitLength / 0x100000000));
    writeUint32BE(tail, tail.length - 4, bitLength >>> 0);

    for (let offset = 0; offset < tail.length; offset += BLOCK_SIZE) {
      compress(state, tail, offset);
    }

    const out = new Uint8Array(DIGEST_SIZE);
    for (let i = 0; i < 5; i += 1) {
      writeUint32BE(out, i * 4, state[i]);
    }
    return out;
  }
}

/**
 * Digest-module descriptor, the JS stand-in for pbkdf2.py's `digestmodule`
 * argument (which defaults to SHA-1).
 */
export const sha1 = {
  name: 'sha1',
  blockSize: BLOCK_SIZE,
  digestSize: DIGEST_SIZE,
  create() {
    return new Sha1();
  },
  digest(data) {
    return new Sha1().update(data).digest();
  },
};

