/**
 * HMAC (RFC 2104), generic over any digest-module descriptor exposing
 * `blockSize`, `digestSize`, `create()` and `digest()`.
 *
 * PBKDF2 calls the PRF thousands of times with a constant key, so the inner
 * and outer pad blocks are absorbed once at construction time and cloned per
 * call instead of being re-hashed.
 */

const INNER_PAD = 0x36;
const OUTER_PAD = 0x5c;

export class Hmac {
  constructor(digestModule, key) {
    this._digestModule = digestModule;
    const { blockSize } = digestModule;

    // Keys longer than one block are hashed down first; shorter keys are
    // zero-padded to the block size.
    const blockKey = new Uint8Array(blockSize);
    blockKey.set(key.length > blockSize ? digestModule.digest(key) : key);

    const innerPad = new Uint8Array(blockSize);
    const outerPad = new Uint8Array(blockSize);
    for (let i = 0; i < blockSize; i += 1) {
      innerPad[i] = blockKey[i] ^ INNER_PAD;
      outerPad[i] = blockKey[i] ^ OUTER_PAD;
    }

    this._inner = digestModule.create().update(innerPad);
    this._outer = digestModule.create().update(outerPad);
  }

  get digestSize() {
    return this._digestModule.digestSize;
  }

  get blockSize() {
    return this._digestModule.blockSize;
  }

  /** HMAC(key, message) for the key bound at construction time. */
  digest(message) {
    const inner = this._inner.copy().update(message).digest();
    return this._outer.copy().update(inner).digest();
  }
}

/** Convenience one-shot: HMAC(key, message) without keeping the object. */
export function hmacDigest(digestModule, key, message) {
  return new Hmac(digestModule, key).digest(message);
}

