/**
 * PBKDF2 (RFC 2898) exposed as a keystream object, matching the interface of
 * the Python `pbkdf2` module (`pbkdf2.PBKDF2(passphrase, salt).read(n)`).
 *
 * Defaults follow that module: HMAC-SHA1 as the PRF and 1000 iterations.
 * `read()` keeps the file-like semantics — leftover bytes of the last derived
 * block are buffered and handed out by the following read, and the block
 * counter continues where it left off, so `read(20) + read(4)` yields exactly
 * the same 24 bytes as a single `read(24)`.
 */

import { concatBytes, toBytes, toHex, writeUint32BE, xorInto } from './bytes.mjs';
import { Hmac } from './hmac.mjs';
import { sha1 } from './sha1.mjs';

export const DEFAULT_ITERATIONS = 1000;

// Block index is serialised as a 32-bit big-endian counter.
const MAX_BLOCK_INDEX = 0xffffffff;

export class PBKDF2 {
  constructor(passphrase, salt, iterations = DEFAULT_ITERATIONS, digestModule = sha1) {
    if (!Number.isInteger(iterations)) {
      throw new TypeError('iterations must be an integer');
    }
    if (iterations < 1) {
      throw new RangeError('iterations must be at least 1');
    }

    this._prf = new Hmac(digestModule, toBytes(passphrase, 'passphrase'));
    this._salt = toBytes(salt, 'salt');
    this._iterations = iterations;
    this._buffer = new Uint8Array(0);
    this._blockNum = 0;
    this._closed = false;
  }

  /** Read the next `count` bytes of the derived keystream. */
  read(count) {
    if (this._closed) {
      throw new Error('file-like object is closed');
    }

    const blocks = [this._buffer];
    let size = this._buffer.length;
    let index = this._blockNum;

    while (size < count) {
      index += 1;
      if (index > MAX_BLOCK_INDEX) {
        throw new RangeError('derived key too long');
      }
      const block = this._deriveBlock(index);
      blocks.push(block);
      size += block.length;
    }

    const buffered = concatBytes(blocks);
    this._buffer = buffered.slice(count);
    this._blockNum = index;
    return buffered.slice(0, count);
  }

  /** Read `octets` bytes and return them as lowercase hex. */
  hexread(octets) {
    return toHex(this.read(octets));
  }

  close() {
    if (!this._closed) {
      this._prf = null;
      this._salt = null;
      this._buffer = null;
      this._closed = true;
    }
  }

  /** The F(P, S, c, i) function: U1 ^ U2 ^ ... ^ Uc. */
  _deriveBlock(index) {
    const seed = new Uint8Array(this._salt.length + 4);
    seed.set(this._salt, 0);
    writeUint32BE(seed, this._salt.length, index);

    let u = this._prf.digest(seed);
    const result = u.slice();
    for (let j = 2; j <= this._iterations; j += 1) {
      u = this._prf.digest(u);
      xorInto(result, u);
    }
    return result;
  }
}

/** One-shot helper: derive `length` bytes for the given passphrase/salt. */
export function deriveKey(passphrase, salt, length, iterations = DEFAULT_ITERATIONS, digestModule = sha1) {
  return new PBKDF2(passphrase, salt, iterations, digestModule).read(length);
}

