/**
 * A small subset of Python's `argparse`, faithful to the behaviours the
 * reference program exhibits: `--opt value` / `--opt=value`, unique-prefix
 * abbreviations, `-h/--help`, the exact usage/help layout, and the three
 * error messages (missing required, missing value, unrecognized arguments)
 * printed to stderr with exit status 2.
 */

// argparse treats a lone `-`, values containing a space, and things that look
// like negative numbers as values rather than options.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const HELP_INDENT = 2;
const MAX_HELP_POSITION = 24;

/** Classification of a command-line token, mirroring `_parse_optional`. */
const VALUE = 'A';
const OPTION = 'O';

function deriveDest(optionStrings) {
  const long = optionStrings.find((flag) => flag.startsWith('--'));
  const chosen = long ?? optionStrings[0];
  return chosen.replace(/^-+/, '').replace(/-/g, '_');
}

export class ArgumentParser {
  constructor(options = {}) {
    this.prog = options.prog ?? 'program';
    this._actions = [];
    this._optionStrings = new Map();

    if (options.addHelp !== false) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  addArgument(flags, config = {}) {
    const optionStrings = Array.isArray(flags) ? flags : [flags];
    const dest = config.dest ?? deriveDest(optionStrings);
    const kind = config.action ?? 'store';
    const action = {
      optionStrings,
      dest,
      kind,
      required: config.required ?? false,
      help: config.help ?? null,
      type: config.type ?? String,
      default: config.default ?? null,
      // `store` consumes one value; `help` consumes none.
      metavar: kind === 'store' ? config.metavar ?? dest.toUpperCase() : null,
    };

    this._actions.push(action);
    for (const flag of optionStrings) {
      this._optionStrings.set(flag, action);
    }
    return action;
  }

  // ---------------------------------------------------------------- parsing

  parseArgs(argv) {
    const namespace = Object.create(null);
    for (const action of this._actions) {
      if (action.kind === 'store') {
        namespace[action.dest] = action.default;
      }
    }

    const seen = new Set();
    const extras = [];
    let i = 0;

    while (i < argv.length) {
      const arg = argv[i];

      if (this._classify(arg) === VALUE) {
        extras.push(arg);
        i += 1;
        continue;
      }

      const match = this._matchOption(arg);
      if (match === null) {
        // Unknown option: collected, then reported after required checks.
        extras.push(arg);
        i += 1;
        continue;
      }

      const { action, optionString, explicitValue } = match;
      seen.add(action);

      if (action.kind === 'help') {
        this._exitWithHelp();
      }

      if (explicitValue !== null) {
        namespace[action.dest] = action.type(explicitValue);
        i += 1;
        continue;
      }

      const next = i + 1 < argv.length ? argv[i + 1] : null;
      if (next === null || this._classify(next) !== VALUE) {
        this._error(`argument ${optionString}: expected one argument`);
      }
      namespace[action.dest] = action.type(next);
      i += 2;
    }

    const missing = this._actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this._error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this._error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }

  _classify(arg) {
    if (arg === '' || arg[0] !== '-') {
      return VALUE;
    }
    if (this._optionStrings.has(arg)) {
      return OPTION;
    }
    if (arg.length === 1) {
      return VALUE; // a bare "-"
    }
    const eq = arg.indexOf('=');
    if (eq > 0 && this._optionStrings.has(arg.slice(0, eq))) {
      return OPTION;
    }
    if (this._prefixMatches(arg).length > 0) {
      return OPTION;
    }
    if (NEGATIVE_NUMBER.test(arg)) {
      return VALUE; // no option string looks like a negative number
    }
    if (arg.includes(' ')) {
      return VALUE;
    }
    return OPTION;
  }

  _prefixMatches(arg) {
    const candidate = arg.indexOf('=') > 0 ? arg.slice(0, arg.indexOf('=')) : arg;
    if (!candidate.startsWith('--')) {
      return [];
    }
    return [...this._optionStrings.keys()].filter((flag) => flag.startsWith(candidate));
  }

  /** Resolve a token to an action, honouring `=` values and abbreviations. */
  _matchOption(arg) {
    const exact = this._optionStrings.get(arg);
    if (exact !== undefined) {
      return { action: exact, optionString: arg, explicitValue: null };
    }

    const eq = arg.indexOf('=');
    if (eq > 0) {
      const flag = arg.slice(0, eq);
      const action = this._optionStrings.get(flag);
      if (action !== undefined) {
        return { action, optionString: flag, explicitValue: arg.slice(eq + 1) };
      }
    }

    const matches = this._prefixMatches(arg);
    if (matches.length > 1) {
      this._error(`ambiguous option: ${arg} could match ${matches.join(', ')}`);
    }
    if (matches.length === 1) {
      const flag = matches[0];
      const action = this._optionStrings.get(flag);
      return {
        action,
        optionString: flag,
        explicitValue: eq > 0 ? arg.slice(eq + 1) : null,
      };
    }
    return null;
  }

  // --------------------------------------------------------------- messages

  formatUsage() {
    const parts = this._actions.map((action) => {
      const flag = action.optionStrings[0];
      const invocation = action.metavar === null ? flag : `${flag} ${action.metavar}`;
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${[this.prog, ...parts].join(' ')}\n`;
  }

  formatHelp() {
    const entries = this._actions.map((action) => ({
      invocation: action.optionStrings
        .map((flag) => (action.metavar === null ? flag : `${flag} ${action.metavar}`))
        .join(', '),
      help: action.help,
    }));

    // argparse: help column = min(longest invocation + indent + 2, 24).
    const longest = entries.reduce((max, entry) => Math.max(max, entry.invocation.length), 0);
    const helpPosition = Math.min(longest + HELP_INDENT + 2, MAX_HELP_POSITION);
    const actionWidth = helpPosition - HELP_INDENT - 2;

    let out = `${this.formatUsage()}\noptions:\n`;
    for (const entry of entries) {
      const indent = ' '.repeat(HELP_INDENT);
      if (!entry.help) {
        out += `${indent}${entry.invocation}\n`;
      } else if (entry.invocation.length <= actionWidth) {
        out += `${indent}${entry.invocation.padEnd(actionWidth)}  ${entry.help}\n`;
      } else {
        out += `${indent}${entry.invocation}\n${' '.repeat(helpPosition)}${entry.help}\n`;
      }
    }
    return out;
  }

  _exitWithHelp() {
    process.stdout.write(this.formatHelp());
    process.exit(0);
  }

  /** usage + `prog: error: message` on stderr, then exit status 2. */
  _error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }
}

