#!/usr/bin/env node
import { basename } from 'node:path';

import { ArgumentParser } from './lib/argparse.mjs';
import { toHex } from './lib/bytes.mjs';
import { PBKDF2 } from './lib/pbkdf2.mjs';

const parser = new ArgumentParser({ prog: basename(process.argv[1] ?? 'test7.mjs') });
parser.addArgument(['--a'], { type: String, required: true }); // passphrase
parser.addArgument(['--b'], { type: String, required: true }); // salt1
parser.addArgument(['--c'], { type: String, required: true }); // salt2
const args = parser.parseArgs(process.argv.slice(2));

// PBKDF2 with the same passphrase but different salts
const key1 = new PBKDF2(args.a, args.b).read(24); // derive a key with the first salt
console.log(toHex(key1));

const key2 = new PBKDF2(args.a, args.c).read(24); // derive a key with the second salt
console.log(toHex(key2));

