#!/usr/bin/env node
// Differential test: /workspace/dataset/test7_executable  vs  /output/test7.mjs
// Compares stdout, stderr and exit code. The argparse `prog` token legitimately
// differs (argparse derives it from argv[0]), so it is normalised in stderr/stdout.
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test7_executable';
const JS = ['/output/test7.mjs'];

const norm = (s) => s.replaceAll('test7_executable', 'PROG').replaceAll('test7.mjs', 'PROG');

function run(cmd, argv, args) {
  const r = spawnSync(cmd, [...argv, ...args], { encoding: 'buffer' });
  return {
    code: r.status,
    out: r.stdout.toString('utf8'),
    err: norm(r.stderr.toString('utf8')),
  };
}

const cases = [
  // documented samples
  ['--a', 'Lm8qH}*x', '--b', 'salt_346554', '--c', 'Ad32jimv'],
  ['--a', 'tgUa2lL[', '--b', 'salt_417146', '--c', 'KdjWSQgf'],
  ['--a', '6gU{zJV7', '--b', 'GHqA33x7mMiuwdKg', '--c', 'salt_007229'],
  ['--a', 'cFfq,.ur', '--b', 'MVhmK4fpPRqXGF9b', '--c', 'NQGqkURv'],
  // help / usage
  ['-h'],
  ['--help'],
  ['--hel'],
  ['--a', 'p', '--b', 's', '--c', 's', '-h'],
  // errors
  [],
  ['--a', 'x'],
  ['--a', 'x', '--b', 'y'],
  ['--a'],
  ['--a', '--b', '--c', 's2'],
  ['--a', 'x', '--b', 'y', '--c', 'z', '--d', 'w'],
  ['--a', 'p', '--b', 's1', '--c', 's2', 'extra'],
  ['--a', 'p', '--b', 's1', '--c', 's2', '--'],
  ['--a', 'p', '--b', 's1', '--c', 's2', '--', 'extra'],
  ['-a', 'p', '--b', 's1', '--c', 's2'],
  ['--ambig'],
  ['--a', '-abc', '--b', 's1', '--c', 's2'],
  ['--a', 'p', '--b', 's1', '--c', 's2', '--a'],
  // value forms
  ['--a=Lm8qH}*x', '--b=salt_346554', '--c=Ad32jimv'],
  ['--a=', '--b', 's1', '--c', 's2'],
  ['--a=-x', '--b', 's1', '--c', 's2'],
  ['--a', 'x', '--a', 'Lm8qH}*x', '--b', 'salt_346554', '--c', 'Ad32jimv'],
  // tricky values
  ['--a', '', '--b', '', '--c', ''],
  ['--a', '-5', '--b', 's1', '--c', 's2'],
  ['--a', '-5.5', '--b', 's1', '--c', 's2'],
  ['--a', '-12345', '--b', 's1', '--c', 's2'],
  ['--a', '-', '--b', 's1', '--c', 's2'],
  ['--a', ' -x', '--b', 's1', '--c', 's2'],
  ['--a', 'p', '--b', 'same', '--c', 'same'],
  // unicode / lengths (SHA-1 padding + HMAC key-reduction boundaries)
  ['--a', '密码é', '--b', '盐1', '--c', 'ünïcødé'],
  ['--a', '🔑🧂', '--b', 'salt🧂', '--c', 'ключ'],
  ['--a', 'p', '--b', 'A'.repeat(51), '--c', 'A'.repeat(52)],
  ['--a', 'p', '--b', 'A'.repeat(55), '--c', 'A'.repeat(56)],
  ['--a', 'p', '--b', 'A'.repeat(59), '--c', 'A'.repeat(60)],
  ['--a', 'p', '--b', 'A'.repeat(63), '--c', 'A'.repeat(64)],
  ['--a', 'p', '--b', 'A'.repeat(119), '--c', 'A'.repeat(120)],
  ['--a', 'k'.repeat(63), '--b', 's1', '--c', 's2'],
  ['--a', 'k'.repeat(64), '--b', 's1', '--c', 's2'],
  ['--a', 'k'.repeat(65), '--b', 's1', '--c', 's2'],
  ['--a', 'k'.repeat(200), '--b', 's1', '--c', 's2'],
  ['--a', '\t\n x', '--b', 's\t1', '--c', 's\n2'],
];

// randomised fuzz over printable ASCII
const ASCII = Array.from({ length: 95 }, (_, i) => String.fromCharCode(32 + i)).join('');
const rnd = (n) => Array.from({ length: n }, () => ASCII[Math.floor(Math.random() * ASCII.length)]).join('');
for (let i = 0; i < 120; i += 1) {
  cases.push(['--a', rnd(1 + (i % 24)), '--b', rnd(1 + ((i * 7) % 40)), '--c', rnd(1 + ((i * 13) % 33))]);
}

let pass = 0;
const failures = [];
for (const args of cases) {
  const a = run(REF, [], args);
  const b = run(process.execPath, JS, args);
  if (a.code === b.code && a.out === b.out && a.err === b.err) {
    pass += 1;
  } else {
    failures.push({ args, ref: a, js: b });
  }
}

console.log(`passed ${pass}/${cases.length}`);
for (const f of failures.slice(0, 10)) {
  console.log('\nFAIL', JSON.stringify(f.args));
  console.log(' ref:', JSON.stringify(f.ref));
  console.log('  js:', JSON.stringify(f.js));
}
process.exit(failures.length === 0 ? 0 : 1);

