#!/usr/bin/env node
// Independent validation of the primitives against published vectors:
// SHA-1 (FIPS 180-2 examples) and PBKDF2-HMAC-SHA1 (RFC 6070).
import { sha1 } from '/output/lib/sha1.mjs';
import { Hmac } from '/output/lib/hmac.mjs';
import { PBKDF2, deriveKey } from '/output/lib/pbkdf2.mjs';
import { toHex } from '/output/lib/bytes.mjs';

const enc = (s) => new TextEncoder().encode(s);
let fail = 0;
const check = (label, got, want) => {
  const ok = got === want;
  if (!ok) fail += 1;
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${label}${ok ? '' : `\n      got  ${got}\n      want ${want}`}`);
};

// ---- SHA-1 ----
check('sha1("")', toHex(sha1.digest(enc(''))), 'da39a3ee5e6b4b0d3255bfef95601890afd80709');
check('sha1("abc")', toHex(sha1.digest(enc('abc'))), 'a9993e364706816aba3e25717850c26c9cd0d89d');
check(
  'sha1(448-bit msg)',
  toHex(sha1.digest(enc('abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'))),
  '84983e441c3bd26ebaae4aa1f95129e5e54670f1',
);
check('sha1(1e6 x "a")', toHex(sha1.digest(enc('a'.repeat(1000000)))), '34aa973cd4c4daa4f61eeb2bdbad27316534016f');
// multi-block / streaming update must equal one-shot
const streamed = sha1.create();
for (const part of ['abcdbcdecdefdefgefghfghighijhijk', 'ijkljklmklmnlmnomnopnopq']) streamed.update(enc(part));
check('sha1 streamed == one-shot', toHex(streamed.digest()), '84983e441c3bd26ebaae4aa1f95129e5e54670f1');

// ---- HMAC-SHA1 (RFC 2202) ----
check(
  'hmac-sha1 key=0x0b*20 "Hi There"',
  toHex(new Hmac(sha1, new Uint8Array(20).fill(0x0b)).digest(enc('Hi There'))),
  'b617318655057264e28bc0b6fb378c8ef146be00',
);
check(
  'hmac-sha1 long key (80 bytes)',
  toHex(new Hmac(sha1, new Uint8Array(80).fill(0xaa)).digest(enc('Test Using Larger Than Block-Size Key - Hash Key First'))),
  'aa4ae5e15272d00e95705637ce8a3b55ed402112',
);

// ---- PBKDF2-HMAC-SHA1 (RFC 6070) ----
check('pbkdf2 c=1 dk=20', toHex(deriveKey('password', 'salt', 20, 1)), '0c60c80f961f0e71f3a9b524af6012062fe037a6');
check('pbkdf2 c=2 dk=20', toHex(deriveKey('password', 'salt', 20, 2)), 'ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957');
check('pbkdf2 c=4096 dk=20', toHex(deriveKey('password', 'salt', 20, 4096)), '4b007901b765489abead49d926f721d065a429c1');
check(
  'pbkdf2 c=4096 dk=25 (multi-block)',
  toHex(deriveKey('passwordPASSWORDpassword', 'saltSALTsaltSALTsaltSALTsaltSALTsalt', 25, 4096)),
  '3d2eec4fe41c849b80c8d83662c0e44a8b291a964cf2f07038',
);
check(
  'pbkdf2 embedded NUL c=4096 dk=16',
  toHex(deriveKey('pass�word', 'sa�lt', 16, 4096)),
  '56fa6aa75548099dcc37d7f03425e0c3',
);

// ---- file-like streaming semantics of read() ----
const oneShot = toHex(new PBKDF2('password', 'salt').read(64));
const pieces = new PBKDF2('password', 'salt');
const chunked = [1, 19, 3, 17, 24].map((n) => toHex(pieces.read(n))).join('');
check('read() chunked == read() one-shot', chunked, oneShot);
check('read(0) is empty', toHex(new PBKDF2('p', 's').read(0)), '');

// UTF-8 handling must match Python's passphrase.encode("UTF-8")
check(
  'utf-8 passphrase == explicit bytes',
  toHex(new PBKDF2('密码é', '盐1').read(24)),
  toHex(new PBKDF2(enc('密码é'), enc('盐1')).read(24)),
);

console.log(fail === 0 ? '\nall vector tests passed' : `\n${fail} vector test(s) failed`);
process.exit(fail === 0 ? 0 : 1);

