const run=(c,a)=>{const r=spawnSync(c,a,{encoding:'buffer'});return r.status+'|'+norm(r.stdout.toString())+'|'+norm(r.stderr.toString());};
// heavy fuzz: wide charset incl. unicode, dashes, equals, spaces, empty
const pool=[...Array(95)].map((_,i)=>String.fromCharCode(32+i));
pool.push('é','密','🔑','ü','я','—','\t');
const rnd=n=>[...Array(n)].map(()=>pool[Math.floor(Math.random()*pool.length)]).join('');
let pass=0,fails=[];
for(let i=0;i<400;i++){
  const args=['--a',rnd(Math.floor(Math.random()*70)),'--b',rnd(Math.floor(Math.random()*70)),'--c',rnd(Math.floor(Math.random()*70))];
  const a=run('/workspace/dataset/test7_executable',args);
  const b=run(process.execPath,['/output/test7.mjs',...args]);
  if(a===b)pass++;else fails.push([args,a,b]);
}
console.log('heavy fuzz passed '+pass+'/400');
fails.slice(0,5).forEach(f=>console.log('FAIL',JSON.stringify(f)));
process.exit(fails.length?1:0);
"; echo "RC=$?"
